"""Cross-checks against independent reference data (fixtures generated by
scripts/oracle/pydraughts_oracle.py; provenance is stored inside each fixture file)."""

from __future__ import annotations

import json
import os
from functools import cache
from pathlib import Path

import pytest

from damas_ai.rules import (
    BOARD_8X8,
    BOARD_10X10,
    BRAZILIAN_PROVISIONAL,
    INTERNATIONAL_PROVISIONAL,
    Geometry,
    legal_moves,
)
from damas_ai.rules.notation import from_fen, to_fen, to_numeric
from damas_ai.rules.perft import perft

FIXTURES = Path(__file__).resolve().parents[1] / "fixtures" / "oracle"
SLOW = os.environ.get("DAMAS_SLOW_TESTS") == "1"
slow = pytest.mark.skipif(not SLOW, reason="set DAMAS_SLOW_TESTS=1 to run deep perft")


@cache
def oracle(name: str) -> dict:
    return json.loads((FIXTURES / f"{name}_pydraughts.json").read_text(encoding="utf-8"))


def as_records(geometry: Geometry, position) -> list:  # type: ignore[no-untyped-def]
    return sorted(
        [to_numeric(geometry, m.origin), to_numeric(geometry, m.destination),
         sorted(to_numeric(geometry, c) for c in m.captured), m.promotes]
        for m in legal_moves(position)
    )


@pytest.mark.parametrize(("name", "geometry"), [("brazilian", BOARD_8X8), ("international", BOARD_10X10)])
def test_move_sets_match_oracle_on_every_sampled_position(name: str, geometry: Geometry) -> None:
    data = oracle(name)
    assert len(data["positions"]) > 1000
    mismatches = []
    for rec in data["positions"]:
        p = from_fen(geometry, rec["fen"])
        assert to_fen(p) == rec["fen"]
        if as_records(geometry, p) != rec["moves"]:
            mismatches.append(rec["fen"])
    assert mismatches == []


def test_oracle_sample_covers_the_hard_cases() -> None:
    """Guard against a weak sample: kings, multi-captures and promotions must be present."""
    data = oracle("brazilian")
    kings = sum(1 for r in data["positions"] if "K" in r["fen"])
    multi = sum(1 for r in data["positions"] if any(len(m[2]) >= 2 for m in r["moves"]))
    promo = sum(1 for r in data["positions"] if any(m[3] for m in r["moves"]))
    assert kings > 500 and multi > 200 and promo > 50


@pytest.mark.parametrize(("name", "geometry"), [("brazilian", BOARD_8X8), ("international", BOARD_10X10)])
def test_symmetry_flip_commutes_with_move_generation(name: str, geometry: Geometry) -> None:
    for rec in oracle(name)["positions"][:1500]:
        p = from_fen(geometry, rec["fen"])
        rot = geometry.rotate180
        # Compare by move identity: for duplicate routes the representative route kept may
        # legitimately differ between a position and its mirror image.
        expected = sorted((rot(m.origin), rot(m.destination),
                           tuple(sorted(rot(c) for c in m.captured)), m.promotes)
                          for m in legal_moves(p))
        got = sorted((m.origin, m.destination, tuple(sorted(m.captured)), m.promotes)
                     for m in legal_moves(p.flipped()))
        assert got == expected, rec["fen"]


@pytest.mark.parametrize("depth", range(1, 8))
def test_brazilian_perft_matches_oracle(depth: int) -> None:
    ref = oracle("brazilian")["perft"][str(depth)]
    assert perft(BRAZILIAN_PROVISIONAL.initial_position(), depth) == ref


@slow
@pytest.mark.parametrize("depth", [8, 9])
def test_brazilian_perft_deep(depth: int) -> None:
    ref = oracle("brazilian")["perft"][str(depth)]
    assert perft(BRAZILIAN_PROVISIONAL.initial_position(), depth) == ref


@pytest.mark.parametrize("depth", range(1, 6))
def test_international_perft_matches_oracle(depth: int) -> None:
    ref = oracle("international")["perft"][str(depth)]
    assert perft(INTERNATIONAL_PROVISIONAL.initial_position(), depth) == ref


@slow
def test_international_perft_depth_6() -> None:
    assert perft(INTERNATIONAL_PROVISIONAL.initial_position(), 6) == oracle("international")["perft"]["6"]


def test_low_depth_perft_hand_verified() -> None:
    """Depth 1 (7) and depth 2 (7 x 7 = 49: no captures are possible after one move each)
    are verified by hand, independently of the oracle."""
    start = BRAZILIAN_PROVISIONAL.initial_position()
    assert perft(start, 1) == 7
    assert perft(start, 2) == 49
